package poker;

enum Command
{
    cmd_place_holder = 0;
    S2C_LoginError = 0x1005; //登录错误
    S2C_LoginSucc = 0x1007; //登录房间成功 通知自己
    S2C_LogoutSucc = 0x1008; //退出房间成功 通知自己
    S2C_ReconnSucc = 0x1009; //重连成功
    S2C_UserEnterRoom = 0x100D; //玩家进入房间 通知其他玩家
    S2C_UserQuitRoom = 0x100E; //玩家退出房间
    S2C_UserReadyStatus = 0x4001; //玩家准备状态
    S2C_UserAutoStatus = 0x4007; //玩家托管状态
    
    S2C_SystemError = 0x5000;
    S2C_GameStart = 0x5001; //游戏开始
    S2C_DealCard = 0x5002; //发牌/补牌
    S2C_RoundStart = 0x5003; //回合开始
    C2S_PickCard = 0x5004; //提交选牌
    S2C_PickCard = 0x5005; //选牌结果
    S2C_StartCompare = 0x5006; //开始比牌
    S2C_CompareResult = 0x5007; //比牌结果
    S2C_MoneyFlow = 0x5008; //结算流水
    S2C_StartDiscard = 0x5009; //开始弃牌
    C2S_DiscardCard = 0x5010; //弃牌请求
    S2C_DiscardCard = 0x5011; //弃牌结果
    S2C_Settle = 0x5012; //结算消息
    C2S_WithdrawMoney = 0x5013; //取钱消息
    S2C_WithdrawMoney = 0x5014; //取钱开始/取钱结果
    S2C_GameOver = 0x5017; //游戏结束
};

// S2C_LoginError
message RspLoginError 
{
    optional uint32 errcode = 1;
};

message RoomInfo 
{
    optional uint32 level = 1;
    optional uint32 basechip = 2;
    optional uint32 deskfee = 3;
    optional uint32 total_game = 4;
};

message RoomUserInfo 
{
    optional uint32 uid = 1;
    optional uint32 seatid = 2;
    optional bool ready = 3;
    optional bool ai = 4; //是否托管
    optional int64 money = 5;
    optional string userinfo = 6; //json格式
};

// S2C_LoginSucc
message RspLoginSuccess
{
    optional RoomInfo room_info = 1;
    optional RoomUserInfo self_info = 2;
    repeated RoomUserInfo others = 3;
};

// S2C_LogoutSucc
message RspLogoutSuccess 
{
    optional uint32 uid = 1; //退出玩家uid
};

// S2C_ReconnSucc
message RspReconnSuccess
{
    optional uint32 uid = 1; //自己uid
    optional uint32 optime = 2; //剩余操作时间(选牌或取钱剩余时间)
    optional RoomInfo room_info = 3;  
    repeated RoomUserInfo user_info = 4;
    optional uint32 round = 5;

    optional uint32 optype = 6; //取钱-101, 选牌-104, 比牌-105, 弃牌-106
    optional uint32 main_type = 7; //主牌型
    repeated RspPickCard pick_records = 8; //选牌记录
    repeated WithdrawUserData withdraw_records = 9; //取钱记录
    repeated uint32 discard_uids = 10; //已弃牌玩家
    repeated RspDealCard handcards = 11; //玩家手牌
    repeated RspMoneyFlow money_flow = 12; //流水数据
};

// S2C_UserEnterRoom
message RspUserEnterRoom 
{
    optional RoomUserInfo userinfo = 1;
};

// S2C_UserQuitRoom
message RspUserQuitRoom
{
    optional uint32 uid = 1;
};

// S2C_UserReadyStatus
message RspUserReadyStatus
{
    optional uint32 uid = 1;
    optional bool ready = 2; // 0-未准备 1-准备 
};

// S2C_UserAutoStatus
message RspUserAutoStatus
{
    optional uint32 uid = 1;
    optional bool ai = 2; //0-未托管 1-托管
};

/////////////////////////////////////////////////////////////////////////

//对局出现异常，对局会结束
message SystemError 
{
    optional uint32 errcode = 1;
    optional string reason = 2;
};

// S2C_GameStart
message RspGameStart
{
    optional uint32 param = 1;
    optional uint32 type = 2; //本局主牌型  1-同点 2-同花 3-连对 4-顺子
}

// S2C_DealCard
message RspDealCard 
{
    optional uint32 uid = 1;
    repeated uint32 add_cards = 2; //新增加的牌(仅自己可见)
    optional uint32 num = 3; //发牌后手牌数量
    optional uint32 left_num = 4; //牌堆剩余数量
    optional uint64 bit_counter = 5; //按位[1,54] 剩余牌记牌器(仅自己可见)
}

// S2C_RoundStart
message RspRoundStart 
{
    optional uint32 round = 1; //客户端可能有动画需求
    optional uint32 optime = 2; //选牌时间
}

//一组牌
message CardGroup
{
    optional uint32 type = 1;   // 牌型 1-同点 2-同花 3-连对 4-顺子
    repeated uint32 cards = 2;
}

// C2S_PickCard 提交选牌
message ReqPickCard 
{
    optional CardGroup pick = 1;
}

// S2C_PickCard 选牌结果
message RspPickCard
{
    optional int32 errcode = 1; //非0提交有错误, 参考错误码
    optional uint32 uid = 2;
    optional CardGroup pick = 3; // 玩家选牌(仅自己可见)
}

// S2C_StartCompare
// comment: 一回合只会发一次
message RspStartCompare
{
    optional uint32 round = 1;
    repeated uint32 type_order = 2; //此回合要比较的牌型
    repeated CompareItem items = 4; //所有玩家摊开手牌
    optional bool draw = 5; //平局-true
}

//一组牌的比较信息
message CompareItem 
{
    optional uint32 uid = 1;
    optional CardGroup pick = 2;
}

// S2C_CompareResult 比牌结果
// comment: 注意平局的时候, 可能同一个round和type,结算多次winner不一样
message RspCompareResult 
{
    optional uint32 round = 1;  //回合数
    optional uint32 type = 2; // 比较牌型
    optional uint32 winner = 3; //赢家uid
    optional uint32 score = 4; //客户端显示的基础牌型倍率(不含暴击倍率)
}

message MoneyItem 
{
    optional uint32 uid = 1;
    optional int64 turn_money = 2;
}

// S2C_MoneyFlow 结算流水
// comment 算钱的时候包含了暴击倍率的钱
message RspMoneyFlow 
{
    repeated MoneyItem items = 1;
    optional uint32 round = 2;
}

// S2C_StartDiscard
message RspStartDiscard
{
    optional uint32 optime = 1;
}

// C2S_DiscardCard
message ReqDiscardCard
{
    optional bool keep = 1; // true-不弃牌
    repeated uint32 cards = 2;
}

// S2C_DiscardCard
message RspDiscardCard
{
    optional int32 errcode = 1; //非0提交有错误, 参考错误码
    optional uint32 uid = 2;
    optional uint32 num = 3; //弃牌后手牌数量
    repeated uint32 cards = 4; //丢弃的牌(仅自己可见)
}

// S2C_Settle 结算消息
message RspSettle 
{
    repeated RspMoneyFlow settle = 1;
}

message WithdrawUserData
{
    optional uint32 uid = 1;
    optional uint32 choose = 2;  //0-未操作 1-取钱完成  2-放弃取钱(破产旁观)
    optional int64 money = 3; //取钱后的钱 放弃则为0
}

// C2S_WithdrawMoney
message ReqWithdrawMoney 
{
    optional uint32 choose = 1; // 1-取钱完成  2-放弃取钱(破产旁观)
};

// S2C_WithdrawMoney
message RspWithdrawMoney 
{
    optional uint32 opt = 1; //1-通知玩家取钱  2-玩家取钱结果 
    optional uint32 optime = 2; //opt==1 破产取钱时间
    repeated uint32 bankrupt_users = 3; //opt==1 破产玩家
    optional WithdrawUserData data = 4; //opt==2 玩家选择结果
};

// S2C_GameOver
message RspGameOver 
{
    optional uint32 param = 1;
};
